# Generated by build.py from recipe.yml for recipe http-retry-a-flaky-endpoint. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'plain', 'few', 'fixed' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'plain/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'few/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'fixed/hello.txt'), "hello from surl`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--fault', '"error;scheme=http;reply=503;path=/hello.txt;times=2"', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --no-progress-meter --retry 3 -w "%{http_code} %{num_retries}\n" http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
